 * Swift-implemented native consent dialog. BLOCKING: `confirm` returns
 * only once the user has answered (or the dialog could not be shown, or
 * was torn down, which must answer `false`). Called on the thread that
 * called the engine method, never the main thread (see the module docs).
 *
 * Only `Ok(true)` is consent. `Ok(false)` and any error are a decline.
 */
public protocol NativeConfirm: AnyObject, Sendable {
    
    func confirm(req: ConfirmPayload) throws  -> Bool
    
}
