// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceNativeConfirm {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceNativeConfirm] = [UniffiVTableCallbackInterfaceNativeConfirm(
        confirm: { (
            uniffiHandle: UInt64,
            req: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<Int8>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> Bool in
                guard let uniffiObj = try? FfiConverterTypeNativeConfirm.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.confirm(
                     req: try FfiConverterTypeConfirmPayload_lift(req)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterBool.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeConfirmError_lower
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterTypeNativeConfirm.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface NativeConfirm: handle missing in uniffiFree")
            }
        }
    )]
}

private func uniffiCallbackInitNativeConfirm() {
    uniffi_acutest_e2ee_ios_fn_init_callback_vtable_nativeconfirm(UniffiCallbackInterfaceNativeConfirm.vtable)
}


