/**
 * Decrypted attachment content for the `e2ee-att://` scheme handler.
 * `mime` has ALREADY been degraded by core's render whitelist: Swift
 * serves it verbatim with `no-store` / `nosniff`, never re-deriving a
 * type from the name or bytes. (No Debug derive: keeps decrypted bytes
 * out of any Debug formatting.)
 */
public struct AttachmentContent {
    public var data: Data
    public var mime: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(data: Data, mime: String) {
        self.data = data
        self.mime = mime
    }
}

#if compiler(>=6)
extension AttachmentContent: Sendable {}
#endif


extension AttachmentContent: Equatable, Hashable {
    public static func ==(lhs: AttachmentContent, rhs: AttachmentContent) -> Bool {
        if lhs.data != rhs.data {
            return false
        }
        if lhs.mime != rhs.mime {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(data)
        hasher.combine(mime)
    }
}



