 * The rendered core-owned copy of one consent dialog. Swift renders it
 * verbatim in a `UIAlertController`; it carries no strings of its own.
 *
 * `kind` is `"warning"` or `"info"`; `default_button` is `"cancel"` or
 * `"confirm"` (which button to make the preferred action).
 */
public struct ConfirmPayload {
    public var title: String
    public var message: String
    /**
     * Label of the button whose press means `confirm == true`.
     */
    public var confirmLabel: String
    public var cancelLabel: String
    public var kind: String
    public var defaultButton: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(title: String, message: String, 
        /**
         * Label of the button whose press means `confirm == true`.
